  t.Run(strings.Join(flags, " "), func(t *testing.T) {
   out, err := execute(t, NewRootCommand(opts), append([]string{"status"}, flags...)...)
   if err != nil { t.Fatalf("status: %v\n%s", err, out) }
   var report struct {
    Integrity string `json:"integrity"`
    Memory map[string]any `json:"memory"`
    Semantic *brainStatusSemantic `json:"semantic"`
   }
   if err := json.Unmarshal([]byte(out), &report); err != nil { t.Fatal(err) }
   if report.Integrity != "not_checked" { t.Fatalf("integrity = %q, want explicit not_checked", report.Integrity) }
   if report.Memory != nil { t.Fatal("status ran the memory audit") }
   if report.Semantic == nil || report.Semantic.Coverage == nil { t.Fatal("missing recorded semantic inventory") }
   for _, name := range []string{"snapshot", "store"} {
    if got := report.Semantic.Freshness.Axes[name].State; got != "present" { t.Fatalf("%s = %q; status should check presence, not contents", name, got) }
   }
   if len(report.Semantic.Coverage.Languages) != 0 { t.Fatal("status scanned the store for coverage histograms") }
  })
 }
 out, err := execute(t, NewRootCommand(opts), "doctor", "--json")
 if err != nil { t.Fatalf("doctor: %v\n%s", err, out) }
 var doctor doctorReport
 if err := json.Unmarshal([]byte(out), &doctor); err != nil { t.Fatal(err) }
 for _, check := range doctor.Checks {
  if check.Name == "semantic" && check.State == "error" { return }
 }
 t.Fatalf("doctor missed corrupt semantic artifacts: %s", out)
}

