base_sha=$(git rev-parse origin/main); base=$(mktemp -d /tmp/brain-status-pr-pinned-base.XXXXXX); git archive "$base_sha" | tar -x -C "$base"; (cd "$base" && go build -o /tmp/brain-status-pr-pinned-before ./cmd/entire-brain) && go build -o /tmp/brain-status-pr-pinned-after ./cmd/entire-brain && BASE_SHA="$base_sha" HEAD_SHA="$(git rev-parse HEAD)" python3.14 - <<'PY'
import subprocess,time,statistics,json,os
samples={'before':[],'after':[]}
for _ in range(5):
 for name in samples:
  t=time.monotonic();subprocess.run(['/tmp/brain-status-pr-pinned-'+name,'status','--json'],stdout=subprocess.DEVNULL,check=True);samples[name].append(time.monotonic()-t)
r={'base':os.environ['BASE_SHA'],'head':os.environ['HEAD_SHA'],'runs':5,'command':'status --json','seconds':samples,'median_seconds':{k:statistics.median(v) for k,v in samples.items()}}
r['speedup']=r['median_seconds']['before']/r['median_seconds']['after']
with open('/tmp/brain-status-pr-pinned-timings.json','w') as f:json.dump(r,f,indent=2)
print(json.dumps(r,indent=2))
PY

